                if val not in VALID_TO_VALUES:
                    error_clap(f"error: invalid value '{val}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                result['to']=val
                idx+=1
                continue
            elif opt_name=="set":
                if seen.get("set",0)>=1:
                    error_clap(f"error: the argument '--set <set> <set>...' cannot be used multiple times\n\nUsage: executable [OPTIONS] [BOOK]", "Usage: executable [OPTIONS] [BOOK]")
                seen["set"]=1
                vals=[]
                if has_eq:
                    vals.append(opt_value)
                    idx+=1
                else:
                    idx+=1
                while idx < len(args):
                    nxt=args[idx]
                    if nxt=="--":
                        break
                    elif nxt.startswith("-"):
                        break
                    else:
                        vals.append(nxt)
                        idx+=1
                if len(vals)==0:
                    error_clap(f"error: a value is required for '--set <set> <set>...' but none was supplied\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                if len(vals)==1:
