            elif long_name=="output":
                if seen.get("output",0)>=1:
                    error_clap(f"error: the argument '--output <output>' cannot be used multiple times\n\nUsage: executable [OPTIONS] [BOOK]", "Usage: executable [OPTIONS] [BOOK]")
                seen["output"]=1
                if idx+1 >= len(args) or args[idx+1].startswith("-"):
                    error_clap(f"error: a value is required for '--output <output>' but none was supplied\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                val=args[idx+1]
                result['output']=val
                idx+=2
                continue
            elif long_name=="to":
                if seen.get("to",0)>=1:
                    error_clap(f"error: the argument '--to <to>' cannot be used multiple times\n\nUsage: executable [OPTIONS] [BOOK]", "Usage: executable [OPTIONS] [BOOK]")
                seen["to"]=1
                if idx+1 >= len(args) or args[idx+1].startswith("-"):
                    error_clap(f"error: a value is required for '--to <to>' but none was supplied\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                val=args[idx+1]
                if val not in VALID_TO_VALUES:
                    error_clap(f"error: invalid value '{val}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                result['to']=val
                idx+=2
                continue
            elif long_name=="lang":
                if seen.get("lang",0)>=1:
                    error_clap(f"error: the argument '--lang <lang>' cannot be used multiple times\n\nUsage: executable [OPTIONS] [BOOK]", "Usage: executable [OPTIONS] [BOOK]")
                seen["lang"]=1
                if idx+1 >= len(args) or args[idx+1].startswith("-"):
                    error_clap(f"error: a value is required for '--lang <lang>' but none was supplied\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
                val=args[idx+1]
                result['lang']=val
                idx+=2
                continue
            else:
                idx+=1
        else:
            positional.append(arg)
            idx+=1
    if len(positional)>1:
        error_clap(f"error: unexpected argument '{positional[1]}' found\n\nUsage: executable [OPTIONS] [BOOK]\n\nFor more information, try '--help'.", "Usage: executable [OPTIONS] [BOOK]")
    if len(positional)==1:
        result['book']=positional[0]
    return result

def check_conflicts(parsed):
    if parsed['quiet'] and parsed['verbose']:
        error_clap(f"error: the argument '--quiet' cannot be used with '--verbose'\n\nUsage: executable --quiet <BOOK>\n\nFor more information, try '--help'.", "Usage: executable --quiet <BOOK>")
    if parsed['output'] is not None and parsed['to'] is None:
        error_clap(f"error: the following required arguments were not provided:\n  --to <to>\n\nUsage: executable --to <to> --output <output> [BOOK]\n\nFor more information, try '--help'.", "Usage: executable --to <to> --output <output> [BOOK]")

# Helper for book parsing
def parse_book_config(book_path):
    try:
        content = open(book_path, "r", encoding="utf-8", errors="ignore").read()
    except:
        raise Exception(f"Could not find file '{book_path}' for book")
    options = {}
    chapters = []
    base_dir = os.path.dirname(os.path.abspath(book_path))
    lines = content.splitlines()
    for idx, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith('"'):
            # quoted example line - treat as comment
            continue
        if stripped.startswith("+"):
            chap = stripped[1:].strip()
            if chap.startswith('"') and chap.endswith('"'):
                chap = chap[1:-1]
            # handle + with maybe no space? already
            if not chap:
                continue
            # Resolve relative
            if not os.path.isabs(chap):
                chap_abs = os.path.join(base_dir, chap)
            else:
                chap_abs = chap
            # Check existence
            if not os.path.exists(chap_abs):
                raise Exception(f"{book_path}:{idx}: Could not find file '{chap_abs}' for book chapter")
            chapters.append(chap_abs)
        else:
            # option line like "key: value" or "key: [a, b]" etc.
            # We handle simple key: value
            if ":" in stripped:
                key, val = stripped.split(":", 1)
                key=key.strip()
                val=val.strip()
                # Remove surrounding quotes if any
                if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                    val=val[1:-1]
                # Handle list like output: [pdf, epub, html]
                if val.startswith("[") and val.endswith("]"):
                    # list
                    inner = val[1:-1].strip()
                    if inner:
                        items = [v.strip().strip('"').strip("'") for v in inner.split(",")]
                        options[key]=items
                    else:
                        options[key]=[]
                else:
                    # For output.* with path, keep as is
                    options[key]=val
                # Validate key known? For now, allow known keys, but if unknown, we should raise warning later
                # List of known keys? For error reporting, we need to know which keys are valid.
                # We'll define known keys set based on --list-options
                # For now, if key is not known, we will treat as error later during rendering (warning)
                # Store unknown for later
                pass
            else:
                # Unknown line format, maybe error? But we can ignore
                pass
    return options, chapters

def count_chars_words(md_path):
    try:
        text = open(md_path, "r", encoding="utf-8", errors="ignore").read()
    except:
        return 0,0
    text = text.replace("\r\n","\n")
    # Split into blocks by blank lines
    blocks_raw = re.split(r'\n\s*\n', text)
    processed_blocks=[]
    for block in blocks_raw:
        block=block.strip()
        if not block:
            continue
        # Code block
        if block.startswith("```"):
            lines=block.split("\n")
            if lines[0].startswith("```"):
                lines=lines[1:]
            if lines and lines[-1].strip()=="```":
                lines=lines[:-1]
            block=" ".join(lines)
        # Remove heading markers
        block=re.sub(r'^#+\s*', '', block, flags=re.MULTILINE)
        block=re.sub(r'^>\s*', '', block, flags=re.MULTILINE)
        lines=block.split("\n")
        cleaned=[]
        for line in lines:
            line=line.strip()
            line=re.sub(r'^(\d+\.\s+|[-*+]\s+)', '', line)
            if line in ["---","***","___"]:
                line="*"
            cleaned.append(line)
        block=" ".join(cleaned)
        block=re.sub(r'\*\*(.*?)\*\*', r'\1', block)
        block=re.sub(r'__(.*?)__', r'\1', block)
        block=re.sub(r'\*(.*?)\*', r'\1', block)
        block=re.sub(r'_(.*?)_', r'\1', block)
        block=re.sub(r'`(.*?)`', r'\1', block)
        block=re.sub(r'~~(.*?)~~', r'\1', block)
        block=re.sub(r'\[([^\]]+)\]\([^\)]+\)', r'\1', block)
        block=re.sub(r'!\[([^\]]*)\]\([^\)]+\)', r'', block)
        block=re.sub(r'\[\^[^\]]+\]', '', block)
        # Keep as is, no collapse multiple spaces (preserve)
        # Only strip leading/trailing
        block=block.strip()
        if block:
            processed_blocks.append(block)
    full_text="".join(processed_blocks)
    chars=len(full_text)
    words=len(re.findall(r'\S+', full_text))
    return chars, words

def compute_stats(book_path):
    options, chapters = parse_book_config(book_path)
    # If no chapters, stats for empty?
    if not chapters:
        # No chapters, return empty stats?
        return "Chapter                        Chars      Words  Chars/Word\n---------\n---------\nTOTAL:                             0          0         NaN\n\n"
    # Determine max_len for formatting
    max_len = max(len(c) for c in chapters)
    w0 = max_len
    w1=11; w2=10; w3=11
    header = f"{'Chapter':<{w0}} {'Chars':>11} {'Words':>10} {'Chars/Word':>11}"
    lines=[header, "---------"]
    total_chars=0
    total_words=0
    for chap in chapters:
        chars, words = count_chars_words(chap)
        total_chars+=chars
        total_words+=words
        if words==0:
            ratio_str="inf" if chars>0 else "NaN"
            row = f"{chap:<{w0}} {chars:>11} {words:>10} {ratio_str:>11}"
        else:
            row = f"{chap:<{w0}} {chars:>11} {words:>10} {chars/words:>11.2f}"
        lines.append(row)
    lines.append("---------")
    if total_words==0:
        total_ratio_str="inf" if total_chars>0 else "NaN"
        total_line = f"{'TOTAL:':<{w0}} {total_chars:>11} {total_words:>10} {total_ratio_str:>11}"
    else:
        total_line = f"{'TOTAL:':<{w0}} {total_chars:>11} {total_words:>10} {total_chars/total_words:>11.2f}"
    lines.append(total_line)
    lines.append("")
    return "\n".join(lines)

def markdown_to_html(md_text, chapter_num=1):
    # Simplified conversion
    # Returns html fragment
    # We'll handle headings, paragraphs, etc.
    html_parts=[]
    # Split into blocks by blank lines
    blocks = re.split(r'\n\s*\n', md_text.strip())
    # For blockquote, list handling, we need more.
    # Simplify: process each block
    para_id=1
    for block in blocks:
        block=block.strip()
        if not block:
            continue
        # Heading
        m=re.match(r'^(#{1,6})\s*(.*)', block)
        if m:
            level=len(m.group(1))
            title=m.group(2).strip()
            # Remove markdown inline from title
            title_clean=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', title)
            title_clean=re.sub(r'\*(.*?)\*', r'<em>\1</em>', title_clean)
            title_clean=re.sub(r'`(.*?)`', r'<code>\1</code>', title_clean)
            if level==1:
                # Chapter heading
                html_parts.append(f"  <h1 id = 'link-{chapter_num}'><span class = 'chapter-header'>Chapter {chapter_num}</span><br />{title_clean}</h1>")
            else:
                # Section
                html_parts.append(f"<h{level}>{title_clean}</h{level}>")
            continue
        # Horizontal rule
        if block.strip() in ["---","***","___"]:
            html_parts.append('<p class = "rule">***</p>')
            continue
        # Blockquote
        if block.startswith(">"):
            # Remove > markers per line
            lines=[re.sub(r'^>\s*','', l) for l in block.split("\n")]
            content=" ".join(lines)
            # Process inline
            content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
            content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
            content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
            content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
            html_parts.append(f"<blockquote><p id = \"para-{para_id}\">{content}</p>\n</blockquote>")
            para_id+=1
            continue
        # Code block
        if block.startswith("```"):
            lines=block.split("\n")
            if lines[0].startswith("```"):
                lines=lines[1:]
            if lines and lines[-1].strip()=="```":
                lines=lines[:-1]
            code="\n".join(lines)
            code=code.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            html_parts.append(f"<pre><span style=\"color:#323232;\">{code}</span>\n\n</pre>")
            continue
        # Table detection: contains | and newline with | and ---
        if "|" in block and "\n" in block:
            # Try to parse as table
            lines=block.split("\n")
            # Check if second line contains --- or |---|
            if len(lines)>=2 and "---" in lines[1]:
                # It's a table
                # First line is header
                header_line=lines[0]
                headers=[c.strip() for c in header_line.strip("|").split("|")]
                headers=[h for h in headers if h]
                rows=[]
                for line in lines[2:]:
                    if not line.strip():
                        continue
                    cols=[c.strip() for c in line.strip("|").split("|")]
                    cols=[c for c in cols if c]
                    if cols:
                        rows.append(cols)
                table_html='<div class = "table">\n    <table>\n<tr>\n'
                for h in headers:
                    table_html+=f"<th>{h}</th>"
                table_html+='</tr>\n'
                for r in rows:
                    table_html+='<tr>\n'
                    for c in r:
                        table_html+=f"<td>{c}</td>"
                    table_html+='</tr>\n'
                table_html+='\n    </table>\n</div>'
                html_parts.append(table_html)
                continue
        # List detection
        lines=block.split("\n")
        # Check if all lines start with list marker
        is_ul = all(re.match(r'^\s*[-*+]\s+', l) for l in lines if l.strip())
        is_ol = all(re.match(r'^\s*\d+\.\s+', l) for l in lines if l.strip())
        if is_ul and len(lines)>=1 and re.match(r'^\s*[-*+]\s+', lines[0]):
            html_parts.append("<ul>")
            for line in lines:
                content=re.sub(r'^\s*[-*+]\s+', '', line)
                content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
                content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
                content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
                content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
                html_parts.append(f"<li><p id = \"para-{para_id}\">{content}</p>\n</li>")
                para_id+=1
            html_parts.append("</ul>")
            continue
        if is_ol and len(lines)>=1 and re.match(r'^\s*\d+\.\s+', lines[0]):
            html_parts.append("<ol>")
            for line in lines:
                content=re.sub(r'^\s*\d+\.\s+', '', line)
                content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
                content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
                content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
                content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
                html_parts.append(f"<li><p id = \"para-{para_id}\">{content}</p>\n</li>")
                para_id+=1
            html_parts.append("</ol>")
            continue
        # Footnote definition like [^1]: content -> handle as footnote, skip for main content? We'll handle separately
        if re.match(r'^\[\^[^\]]+\]:', block):
            # footnote definition, will be rendered in notes section, but for now ignore in main flow
            # We'll extract and handle later
            continue
        # Paragraph with footnotes and other inline
        # Handle footnote references [^1] -> convert to footnote reference
        # Simple: replace [^1] with footnote link
        def repl_foot(m):
            num=m.group(1)
            return f'<a class = "footnote_reference" href = "#note-dest-1-{num}" id = "note-source-1-{num}"><sup>[{num}]</sup></a>'
        block_temp = re.sub(r'\[\^(\d+)\]', repl_foot, block)
        # Process inline markdown
        block_temp=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', block_temp)
        block_temp=re.sub(r'\*(.*?)\*', r'<em>\1</em>', block_temp)
        block_temp=re.sub(r'`(.*?)`', r'<code>\1</code>', block_temp)
        block_temp=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', block_temp)
        # Handle images: ![alt](src) -> <div class="image"><img ...></div> if standalone else inline?
        # For simplicity, if block is just image alone, treat as standalone
        if re.match(r'^\s*!\[.*\]\(.*\)\s*$', block_temp):
            m=re.match(r'.*!\[([^\]]*)\]\(([^\)]+)\).*', block_temp)
            if m:
                alt=m.group(1)
                src=m.group(2)
                html_parts.append(f'<div class = "image"><img src = "{src}" alt = "{alt}" /></div>')
                continue
        else:
            # replace inline images
            block_temp=re.sub(r'!\[([^\]]*)\]\(([^\)]+)\)', r'<img src = "\2" alt = "\1" />', block_temp)
        # If block contains footnote definitions already removed, we need to handle notes section
        # For now, wrap as paragraph
        html_parts.append(f'<p id = "para-{para_id}">{block_temp}</p>')
        para_id+=1
        # After paragraph, check if there were footnotes in original block, we should add notes section
        # Find footnote definitions in original md_text
        # We'll handle footnotes globally later
    # After processing all blocks, check for footnotes in original text
    footnote_matches = re.findall(r'\[\^(\d+)\]:\s*(.*)', md_text)
    if footnote_matches:
        html_parts.append('<section class = "notes" >\n <h2 class = "notes">Notes</h2>\n<table class = "notes">')
        for num, content in footnote_matches:
            # Process footnote content inline
            content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
            content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
            content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
            html_parts.append(f'<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n  <a rel = "footnote" href = "#note-source-1-{num}">[{num}]</a>\n</p>\n\n </td>\n <td class = "note">\n  <aside class = "footnote" id = "note-dest-1-{num}"><p id = "para-{para_id}">{content}</p>\n</aside>\n  </td>\n</tr>')
            para_id+=1
        html_parts.append('</table>\n</section>')
    return "\n".join(html_parts)

def render_html_standalone(options, chapters_html, title, author, lang, output_path, quiet, verbose, no_fancy, force_emoji):
    # Load templates
    html_template = TEMPLATES.get("html.standalone.template", "")
