    css = TEMPLATES.get("html.css","")
    colors = TEMPLATES.get("html.css.colors","")
    # Combine
    style = css + "\n" + colors
    # Add html.css.print etc? Not needed for standalone
    # Load JS
    js = TEMPLATES.get("html.js","")
    # For verbose, we may need to handle highlight etc, but ignore
    # Prepare replacements
    # Simple placeholder substitution
    # The template uses {{var}} and {% if ... %} etc. We need to handle conditionals at least for toc etc.
    # For minimal, we will do simple replacements and strip conditionals
