    # Read markdown file, handle YAML frontmatter if present
    md_text = open(md_path, "r", encoding="utf-8", errors="ignore").read()
    # Extract YAML frontmatter if begins with ---
    options={}
    content=md_text
    if md_text.startswith("---"):
        # Find second ---
        end = md_text.find("---", 3)
        if end!=-1:
            yaml_block = md_text[3:end]
            content = md_text[end+3:].lstrip("\n")
            # Parse yaml block for options like title, author, etc.
            for line in yaml_block.splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if ":" in line:
