def check_conflicts(parsed):
    if parsed['quiet'] and parsed['verbose']:
        error_clap(f"error: the argument '--quiet' cannot be used with '--verbose'\n\nUsage: executable --quiet <BOOK>\n\nFor more information, try '--help'.", "Usage: executable --quiet <BOOK>")
    if parsed['output'] is not None and parsed['to'] is None:
        error_clap(f"error: the following required arguments were not provided:\n  --to <to>\n\nUsage: executable --to <to> --output <output> [BOOK]\n\nFor more information, try '--help'.", "Usage: executable --to <to> --output <output> [BOOK]")
def parse_book_config(book_path):
    try:
        content = open(book_path, "r", encoding="utf-8", errors="ignore").read()
    except:
        raise Exception(f"Could not find file '{book_path}' for book")
    options={}
    chapters=[]
    base_dir = os.path.dirname(os.path.abspath(book_path))
    lines = content.splitlines()
    for idx, line in enumerate(lines, start=1):
        stripped=line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith('"'):
            continue
        if stripped.startswith("+"):
            chap = stripped[1:].strip()
            if chap.startswith('"') and chap.endswith('"'):
                chap=chap[1:-1]
            if not chap:
                continue
            if not os.path.isabs(chap):
                chap_abs = os.path.join(base_dir, chap)
            else:
                chap_abs=chap
            if not os.path.exists(chap_abs):
                raise Exception(f"{book_path}:{idx}: Could not find file '{chap_abs}' for book chapter")
            chapters.append(chap_abs)
        else:
            if ":" in stripped:
                key,val=stripped.split(":",1)
                key=key.strip()
                val=val.strip()
                if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                    val=val[1:-1]
                if val.startswith("[") and val.endswith("]"):
                    inner=val[1:-1].strip()
                    if inner:
                        items=[v.strip().strip('"').strip("'") for v in inner.split(",")]
                        options[key]=items
                    else:
                        options[key]=[]
                else:
                    options[key]=val
    return options, chapters
def count_chars_words(md_path):
    try:
        text = open(md_path, "r", encoding="utf-8", errors="ignore").read()
    except:
        return 0,0
    text=text.replace("\r\n","\n")
    blocks_raw=re.split(r'\n\s*\n', text)
    processed_blocks=[]
    for block in blocks_raw:
        block=block.strip()
        if not block:
            continue
        if block.startswith("```"):
            lines=block.split("\n")
            if lines[0].startswith("```"):
                lines=lines[1:]
            if lines and lines[-1].strip()=="```":
                lines=lines[:-1]
            block=" ".join(lines)
        block=re.sub(r'^#+\s*', '', block, flags=re.MULTILINE)
        block=re.sub(r'^>\s*', '', block, flags=re.MULTILINE)
        lines=block.split("\n")
        cleaned=[]
        for line in lines:
            line=line.strip()
            line=re.sub(r'^(\d+\.\s+|[-*+]\s+)', '', line)
            if line in ["---","***","___"]:
                line="*"
            cleaned.append(line)
        block=" ".join(cleaned)
        block=re.sub(r'\*\*(.*?)\*\*', r'\1', block)
        block=re.sub(r'__(.*?)__', r'\1', block)
        block=re.sub(r'\*(.*?)\*', r'\1', block)
        block=re.sub(r'_(.*?)_', r'\1', block)
        block=re.sub(r'`(.*?)`', r'\1', block)
        block=re.sub(r'~~(.*?)~~', r'\1', block)
        block=re.sub(r'\[([^\]]+)\]\([^\)]+\)', r'\1', block)
        block=re.sub(r'!\[([^\]]*)\]\([^\)]+\)', r'', block)
        block=re.sub(r'\[\^[^\]]+\]', '', block)
        block=block.strip()
        if block:
            processed_blocks.append(block)
    full_text="".join(processed_blocks)
    chars=len(full_text)
    words=len(re.findall(r'\S+', full_text))
    return chars, words
def compute_stats(book_path):
    options,chapters=parse_book_config(book_path)
    if not chapters:
        return "Chapter                        Chars      Words  Chars/Word\n---------\n---------\nTOTAL:                             0          0         NaN\n\n"
    max_len=max(len(c) for c in chapters)
    w0=max_len
    w1=11;w2=10;w3=11
    header=f"{'Chapter':<{w0}} {'Chars':>11} {'Words':>10} {'Chars/Word':>11}"
    lines=[header,"---------"]
    total_chars=0;total_words=0
    for chap in chapters:
        chars,words=count_chars_words(chap)
        total_chars+=chars;total_words+=words
        if words==0:
            ratio_str="inf" if chars>0 else "NaN"
            row=f"{chap:<{w0}} {chars:>11} {words:>10} {ratio_str:>11}"
        else:
            row=f"{chap:<{w0}} {chars:>11} {words:>10} {chars/words:>11.2f}"
        lines.append(row)
    lines.append("---------")
    if total_words==0:
        total_ratio_str="inf" if total_chars>0 else "NaN"
        total_line=f"{'TOTAL:':<{w0}} {total_chars:>11} {total_words:>10} {total_ratio_str:>11}"
    else:
        total_line=f"{'TOTAL:':<{w0}} {total_chars:>11} {total_words:>10} {total_chars/total_words:>11.2f}"
    lines.append(total_line)
    lines.append("")
    return "\n".join(lines)
def markdown_to_html(md_text, chapter_num=1):
    html_parts=[]
    blocks=re.split(r'\n\s*\n', md_text.strip())
    para_id=1
    for block in blocks:
        block=block.strip()
        if not block:
            continue
        m=re.match(r'^(#{1,6})\s*(.*)', block)
        if m:
            level=len(m.group(1))
            title=m.group(2).strip()
            title_clean=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', title)
            title_clean=re.sub(r'\*(.*?)\*', r'<em>\1</em>', title_clean)
            title_clean=re.sub(r'`(.*?)`', r'<code>\1</code>', title_clean)
            if level==1:
                html_parts.append(f"  <h1 id = 'link-{chapter_num}'><span class = 'chapter-header'>Chapter {chapter_num}</span><br />{title_clean}</h1>")
            else:
                html_parts.append(f"<h{level}>{title_clean}</h{level}>")
            continue
        if block.strip() in ["---","***","___"]:
            html_parts.append('<p class = "rule">***</p>')
            continue
        if block.startswith(">"):
            lines=[re.sub(r'^>\s*','', l) for l in block.split("\n")]
            content=" ".join(lines)
            content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
            content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
            content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
            content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
            html_parts.append(f"<blockquote><p id = \"para-{para_id}\">{content}</p>\n</blockquote>")
            para_id+=1
            continue
        if block.startswith("```"):
            lines=block.split("\n")
            if lines[0].startswith("```"):
                lines=lines[1:]
            if lines and lines[-1].strip()=="```":
                lines=lines[:-1]
            code="\n".join(lines)
            code=code.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            html_parts.append(f"<pre><span style=\"color:#323232;\">{code}</span>\n\n</pre>")
            continue
        if "|" in block and "\n" in block:
            lines=block.split("\n")
            if len(lines)>=2 and "---" in lines[1]:
                header_line=lines[0]
                headers=[c.strip() for c in header_line.strip("|").split("|")]
                headers=[h for h in headers if h]
                rows=[]
                for line in lines[2:]:
                    if not line.strip():
                        continue
                    cols=[c.strip() for c in line.strip("|").split("|")]
                    cols=[c for c in cols if c]
                    if cols:
                        rows.append(cols)
                table_html='<div class = "table">\n    <table>\n<tr>\n'
                for h in headers:
                    table_html+=f"<th>{h}</th>"
                table_html+='</tr>\n'
                for r in rows:
                    table_html+='<tr>\n'
                    for c in r:
                        table_html+=f"<td>{c}</td>"
                    table_html+='</tr>\n'
                table_html+='\n    </table>\n</div>'
                html_parts.append(table_html)
                continue
        lines=block.split("\n")
        is_ul = all(re.match(r'^\s*[-*+]\s+', l) for l in lines if l.strip())
        is_ol = all(re.match(r'^\s*\d+\.\s+', l) for l in lines if l.strip())
        if is_ul and len(lines)>=1 and re.match(r'^\s*[-*+]\s+', lines[0]):
            html_parts.append("<ul>")
            for line in lines:
                content=re.sub(r'^\s*[-*+]\s+', '', line)
                content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
                content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
                content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
                content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
                html_parts.append(f"<li><p id = \"para-{para_id}\">{content}</p>\n</li>")
                para_id+=1
            html_parts.append("</ul>")
            continue
        if is_ol and len(lines)>=1 and re.match(r'^\s*\d+\.\s+', lines[0]):
            html_parts.append("<ol>")
            for line in lines:
                content=re.sub(r'^\s*\d+\.\s+', '', line)
                content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
                content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
                content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
                content=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', content)
                html_parts.append(f"<li><p id = \"para-{para_id}\">{content}</p>\n</li>")
                para_id+=1
            html_parts.append("</ol>")
            continue
        if re.match(r'^\[\^[^\]]+\]:', block):
            continue
        def repl_foot(m):
            num=m.group(1)
            return f'<a class = "footnote_reference" href = "#note-dest-1-{num}" id = "note-source-1-{num}"><sup>[{num}]</sup></a>'
        block_temp = re.sub(r'\[\^(\d+)\]', repl_foot, block)
        block_temp=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', block_temp)
        block_temp=re.sub(r'\*(.*?)\*', r'<em>\1</em>', block_temp)
        block_temp=re.sub(r'`(.*?)`', r'<code>\1</code>', block_temp)
        block_temp=re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href = "\2">\1</a>', block_temp)
        if re.match(r'^\s*!\[.*\]\(.*\)\s*$', block_temp):
            m=re.match(r'.*!\[([^\]]*)\]\(([^\)]+)\).*', block_temp)
            if m:
                alt=m.group(1)
                src=m.group(2)
                html_parts.append(f'<div class = "image"><img src = "{src}" alt = "{alt}" /></div>')
                continue
        else:
            block_temp=re.sub(r'!\[([^\]]*)\]\(([^\)]+)\)', r'<img src = "\2" alt = "\1" />', block_temp)
        html_parts.append(f'<p id = "para-{para_id}">{block_temp}</p>')
        para_id+=1
    footnote_matches = re.findall(r'\[\^(\d+)\]:\s*(.*)', md_text)
    if footnote_matches:
        html_parts.append('<section class = "notes" >\n <h2 class = "notes">Notes</h2>\n<table class = "notes">')
        for num, content in footnote_matches:
            content=re.sub(r'\*\*(.*?)\*\*', r'<b>\1</b>', content)
            content=re.sub(r'\*(.*?)\*', r'<em>\1</em>', content)
            content=re.sub(r'`(.*?)`', r'<code>\1</code>', content)
            html_parts.append(f'<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n  <a rel = "footnote" href = "#note-source-1-{num}">[{num}]</a>\n</p>\n\n </td>\n <td class = "note">\n  <aside class = "footnote" id = "note-dest-1-{num}"><p id = "para-{para_id}">{content}</p>\n</aside>\n  </td>\n</tr>')
            para_id+=1
        html_parts.append('</table>\n</section>')
    return "\n".join(html_parts)
def render_html_standalone(options, chapters_html, title, author, lang, output_path, quiet, verbose, no_fancy, force_emoji):
