def render_book(book_path, parsed, quiet, verbose, no_fancy, force_emoji, lang):
    options, chapters = parse_book_config(book_path)
    if parsed.get('set'):
        vals=parsed['set']
        if len(vals)%2==1:
            raise Exception("An odd number of arguments was passed to --set, but it takes\na list of key value pairs.")
