        header += f'\n\t  <div id = "autograph">\n\t    {options.get("autograph")}\n\t  </div>'
    chapters_combined=""
    for idx, html in enumerate(chapters_html):
        chapters_combined+=f'<div id = "chapter-{idx}" class = "chapter">\n{html}\n</div>\n\n'
    print_css = TEMPLATES.get("html.css.print","")
    full_html = f"""<!DOCTYPE html>
<html lang="{lang}">
