        generated.append(("epub", output_epub))
    if output_tex:
        generated.append(("tex", output_tex))
    if output_pdf:
        generated.append(("pdf", output_pdf))
    return generated

def render_single(md_path, output_path, to_format, parsed, quiet, verbose, no_fancy, force_emoji):
    md_text=open(md_path, "r", encoding="utf-8", errors="ignore").read()
    options={}
    content=md_text
    if md_text.startswith("---"):
        end=md_text.find("---",3)
        if end!=-1:
            yaml_block=md_text[3:end]
            content=md_text[end+3:].lstrip("\n")
            for line in yaml_block.splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if ":" in line:
                    k,v=line.split(":",1)
                    k=k.strip();v=v.strip().strip('"').strip("'")
                    options[k]=v
    title=options.get("title","")
    author=options.get("author","")
    lang=options.get("lang","en")
    if to_format=="html":
        html=markdown_to_html(content, chapter_num=1)
