        with open(os.path.join(oebps, "toc.ncx"), "w", encoding="utf-8") as f:
            f.write(f'<?xml version="1.0" encoding="UTF-8"?><ncx xmlns="http://www.daisy.org/z3986/2005/ncx/"><head><meta name="dtb:uid" content="urn:uuid:12345"/></head><docTitle><text>{title}</text></docTitle><navMap><navPoint id="navPoint-1" playOrder="1"><navLabel><text>Chapter 1</text></navLabel><content src="chapter_000.xhtml"/></navPoint></navMap></ncx>')
        with open(os.path.join(oebps, "nav.xhtml"), "w", encoding="utf-8") as f:
