        os.makedirs(os.path.dirname(os.path.abspath(output_path)) if os.path.dirname(output_path) else ".", exist_ok=True)
        with zipfile.ZipFile(output_path, 'w') as z:
            z.write(os.path.join(tmpdir, "mimetype"), "mimetype", compress_type=zipfile.ZIP_STORED)
            for root, dirs, files in os.walk(tmpdir):
                for file in files:
                    if file=="mimetype":
                        continue
                    full=os.path.join(root,file)
                    arc=os.path.relpath(full, tmpdir)
                    z.write(full, arc, compress_type=zipfile.ZIP_DEFLATED)
        shutil.rmtree(tmpdir)
    elif to_format=="tex":
        tex_template=TEMPLATES.get("tex.template","")
