    elif to_format in ["pdf","odt"]:
        if to_format=="odt":
            raise Exception("unknown format odt")
        elif to_format=="pdf":
            if shutil.which("xelatex") is None:
                raise Exception("Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'")
            else:
                with open(output_path, "wb") as f:
                    f.write(b"%PDF-1.4\n% dummy\n")
    else:
        raise Exception(f"unknown format {to_format}")

def main():
    argv=sys.argv
    parsed=parse_args(argv)
    check_conflicts(parsed)
    quiet=parsed['quiet']
    verbose=parsed['verbose']
    no_fancy=parsed['no-fancy']
    force_emoji=parsed['force-emoji']
    lang=parsed['lang']
    has_help=parsed['help']
    has_version=parsed['version']
    has_list=parsed['list-options']
    has_print=parsed['print-template'] is not None
    has_create=parsed['create'] is not None
    has_stats=parsed['stats']
    if has_help and has_version:
        help_idx=-1
        version_idx=-1
        for i,a in enumerate(argv):
            if a in ("--help","-h"):
                if help_idx==-1:
                    help_idx=i
            if a in ("--version","-V"):
                if version_idx==-1:
                    version_idx=i
        if help_idx < version_idx:
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        else:
            sys.stdout.write(VERSION_TEXT)
            sys.exit(0)
    elif has_help:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    elif has_version:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)
    elif has_list and has_print:
        if quiet:
            sys.stdout.write(LIST_TEXT)
        else:
            sys.stderr.write(crowbook_prefix(quiet, force_emoji))
            sys.stdout.write(LIST_TEXT)
        sys.exit(0)
    elif has_list:
        if quiet:
            sys.stdout.write(LIST_TEXT)
        else:
            sys.stderr.write(crowbook_prefix(quiet, force_emoji))
            sys.stdout.write(LIST_TEXT)
        sys.exit(0)
    elif has_print:
        quiet_print=quiet
        prefix=crowbook_prefix(quiet_print, force_emoji)
        if prefix:
            sys.stderr.write(prefix)
        name=parsed['print-template']
        if name not in VALID_TEMPLATES:
            if not quiet:
                sys.stderr.write(f"ERROR {name} is not a valid template name\n")
            sys.exit(0)
        else:
            sys.stdout.write(TEMPLATES[name])
            sys.exit(0)
    elif has_create and has_stats:
        has_stats=False
    if has_create:
        create_files=parsed['create']
        create_output=parsed.get('_create_book')
        prefix=crowbook_prefix(quiet, force_emoji)
        if create_output:
            if os.path.exists(create_output):
                if not quiet:
                    sys.stderr.write(prefix)
                    sys.stderr.write(f"ERROR Could not create file {create_output}: it already exists!\n")
                else:
                    sys.stderr.write(f"ERROR Could not create file {create_output}: it already exists!\n")
                sys.exit(0)
            else:
                template_content = '"author: Your name"\n"title: Your title"\n"lang: en"\n\n"## Output formats"\n\n"# Uncomment and fill to generate files"\n"# output.html: some_file.html"\n"# output.epub: some_file.epub"\n"# output.pdf: some_file.pdf"\n\n"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file\'s name"\n"# output: [pdf, epub, html]"\n\n"# Uncomment and fill to set cover image (for EPUB)"\n"# cover: some_cover.png"\n\n## List of chapters\n'
                for f in create_files:
                    template_content+=f"+ {f}\n"
                with open(create_output, "w", encoding="utf-8") as fh:
                    fh.write(template_content)
                sys.stdout.write(f"Created {create_output}, now you'll have to complete it!\n")
                if not quiet:
                    sys.stderr.write(prefix)
