                raise Exception(f"Error rendering pdf: {str(e)}")
    generated=[]
    if output_html:
        generated.append(("html", output_html))
    if output_dir:
        generated.append(("html.dir", output_dir))
    if output_epub:
        generated.append(("epub", output_epub))
    if output_tex:
        generated.append(("tex", output_tex))
    if output_pdf:
        generated.append(("pdf", output_pdf))
    return generated

def render_single(md_path, output_path, to_format, parsed, quiet, verbose, no_fancy, force_emoji):
    md_text=open(md_path, "r", encoding="utf-8", errors="ignore").read()
    options={}
    content=md_text
    if md_text.startswith("---"):
        end=md_text.find("---",3)
        if end!=-1:
            yaml_block=md_text[3:end]
            content=md_text[end+3:].lstrip("\n")
            for line in yaml_block.splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if ":" in line:
                    k,v=line.split(":",1)
                    k=k.strip();v=v.strip().strip('"').strip("'")
                    options[k]=v
    title=options.get("title","")
    author=options.get("author","")
    lang=options.get("lang","en")
    if to_format=="html":
        html=markdown_to_html(content, chapter_num=1)
        render_html_standalone(options, [html], title, author, lang, output_path, quiet, verbose, no_fancy, force_emoji)
    elif to_format=="epub":
        html=markdown_to_html(content, chapter_num=1)
        tmpdir=tempfile.mkdtemp()
        oebps=os.path.join(tmpdir, "OEBPS")
        meta=os.path.join(tmpdir, "META-INF")
        os.makedirs(oebps);os.makedirs(meta)
        with open(os.path.join(tmpdir, "mimetype"), "w", encoding="utf-8") as f:
            f.write("application/epub+zip")
        with open(os.path.join(meta, "container.xml"), "w", encoding="utf-8") as f:
            f.write('<?xml version="1.0" encoding="UTF-8"?><container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>')
        with open(os.path.join(oebps, "stylesheet.css"), "w", encoding="utf-8") as f:
            f.write(TEMPLATES.get("epub.css",""))
        chap_path=os.path.join(oebps, "chapter_000.xhtml")
        chapter_template=TEMPLATES.get("epub.chapter.xhtml","")
        if "{{content}}" in chapter_template:
            xhtml=chapter_template.replace("{{content}}", html).replace("{{lang}}", lang).replace("{{chapter_title_raw}}", "Chapter 1")
        else:
            xhtml=f'<?xml version="1.0" encoding="UTF-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>Chapter 1</title><link rel="stylesheet" href="stylesheet.css" /></head><body>{html}</body></html>'
        with open(chap_path, "w", encoding="utf-8") as f:
            f.write(xhtml)
        with open(os.path.join(oebps, "content.opf"), "w", encoding="utf-8") as f:
            f.write(f'<?xml version="1.0" encoding="UTF-8"?><package version="3.0" xmlns="http://www.idpf.org/2007/opf"><metadata><dc:title xmlns:dc="http://purl.org/dc/elements/1.1/">{title}</dc:title><dc:creator xmlns:dc="http://purl.org/dc/elements/1.1/">{author}</dc:creator><dc:language xmlns:dc="http://purl.org/dc/elements/1.1/">{lang}</dc:language></metadata><manifest><item id="stylesheet" href="stylesheet.css" media-type="text/css"/><item id="chapter_000" href="chapter_000.xhtml" media-type="application/xhtml+xml"/><item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/><item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/></manifest><spine toc="ncx"><itemref idref="chapter_000" /></spine></package>')
        with open(os.path.join(oebps, "toc.ncx"), "w", encoding="utf-8") as f:
            f.write(f'<?xml version="1.0" encoding="UTF-8"?><ncx xmlns="http://www.daisy.org/z3986/2005/ncx/"><head><meta name="dtb:uid" content="urn:uuid:12345"/></head><docTitle><text>{title}</text></docTitle><navMap><navPoint id="navPoint-1" playOrder="1"><navLabel><text>Chapter 1</text></navLabel><content src="chapter_000.xhtml"/></navPoint></navMap></ncx>')
        with open(os.path.join(oebps, "nav.xhtml"), "w", encoding="utf-8") as f:
            f.write(f'<?xml version="1.0" encoding="UTF-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>Table of Contents</title></head><body><nav xmlns:epub="http://www.idpf.org/2007/ops" epub:type="toc"><ol><li><a href="chapter_000.xhtml">Chapter 1</a></li></ol></nav></body></html>')
        os.makedirs(os.path.dirname(os.path.abspath(output_path)) if os.path.dirname(output_path) else ".", exist_ok=True)
        with zipfile.ZipFile(output_path, 'w') as z:
            z.write(os.path.join(tmpdir, "mimetype"), "mimetype", compress_type=zipfile.ZIP_STORED)
            for root, dirs, files in os.walk(tmpdir):
                for file in files:
                    if file=="mimetype":
                        continue
                    full=os.path.join(root,file)
                    arc=os.path.relpath(full, tmpdir)
                    z.write(full, arc, compress_type=zipfile.ZIP_DEFLATED)
        shutil.rmtree(tmpdir)
    elif to_format=="tex":
        tex_template=TEMPLATES.get("tex.template","")
        tex_content=markdown_to_html(content)
        tex_output=tex_template
        tex_output=re.sub(r'<#.*?#>', '', tex_output)
        replacements={"title":title,"author":author,"description":"","content":tex_content,"class":"book","tex_lang":lang,"papersize":"a5paper","margin_top":"2cm","margin_bottom":"1.5cm","subtitle":options.get("subtitle",""),"autograph":options.get("autograph",""),"version":options.get("version",""),"license":options.get("license",""),"tex_size":"","chapter_name":"","part_name":""}
        for k,v in replacements.items():
            tex_output=tex_output.replace(f"<<{k}>>", v)
        tex_output=re.sub(r'<<[^>]+>>', '', tex_output)
        os.makedirs(os.path.dirname(os.path.abspath(output_path)) if os.path.dirname(output_path) else ".", exist_ok=True)
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(tex_output)
    elif to_format=="html.dir":
        raise Exception(f"thread 'main' panicked at src/lib/html_dir.rs:464:64:\ncalled `Result::unwrap()` on an `Err` value: Error {{ source: Source {{ file: None, line: None }}, inner: InvalidOption(\"option 'output.html.dir' is not present\") }}")
    elif to_format in ["pdf","odt"]:
        if to_format=="odt":
            raise Exception("unknown format odt")
        elif to_format=="pdf":
            if shutil.which("xelatex") is None:
                raise Exception("Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'")
            else:
                with open(output_path, "wb") as f:
                    f.write(b"%PDF-1.4\n% dummy\n")
    else:
        raise Exception(f"unknown format {to_format}")

def main():
    argv=sys.argv
    parsed=parse_args(argv)
    check_conflicts(parsed)
    quiet=parsed['quiet']
    verbose=parsed['verbose']
    no_fancy=parsed['no-fancy']
    force_emoji=parsed['force-emoji']
    lang=parsed['lang']
    has_help=parsed['help']
    has_version=parsed['version']
    has_list=parsed['list-options']
    has_print=parsed['print-template'] is not None
    has_create=parsed['create'] is not None
    has_stats=parsed['stats']
    if has_help and has_version:
        help_idx=-1
        version_idx=-1
        for i,a in enumerate(argv):
            if a in ("--help","-h"):
                if help_idx==-1:
                    help_idx=i
            if a in ("--version","-V"):
                if version_idx==-1:
                    version_idx=i
        if help_idx < version_idx:
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        else:
            sys.stdout.write(VERSION_TEXT)
            sys.exit(0)
    elif has_help:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    elif has_version:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)
    elif has_list and has_print:
        if quiet:
            sys.stdout.write(LIST_TEXT)
        else:
            sys.stderr.write(crowbook_prefix(quiet, force_emoji))
            sys.stdout.write(LIST_TEXT)
        sys.exit(0)
    elif has_list:
        if quiet:
            sys.stdout.write(LIST_TEXT)
        else:
            sys.stderr.write(crowbook_prefix(quiet, force_emoji))
            sys.stdout.write(LIST_TEXT)
        sys.exit(0)
    elif has_print:
        quiet_print=quiet
        prefix=crowbook_prefix(quiet_print, force_emoji)
        if prefix:
            sys.stderr.write(prefix)
        name=parsed['print-template']
        if name not in VALID_TEMPLATES:
            if not quiet:
                sys.stderr.write(f"ERROR {name} is not a valid template name\n")
            sys.exit(0)
        else:
            sys.stdout.write(TEMPLATES[name])
            sys.exit(0)
    elif has_create and has_stats:
        has_stats=False
    if has_create:
        create_files=parsed['create']
        create_output=parsed.get('_create_book')
        prefix=crowbook_prefix(quiet, force_emoji)
        if create_output:
            if os.path.exists(create_output):
                if not quiet:
                    sys.stderr.write(prefix)
                    sys.stderr.write(f"ERROR Could not create file {create_output}: it already exists!\n")
                else:
                    sys.stderr.write(f"ERROR Could not create file {create_output}: it already exists!\n")
                sys.exit(0)
            else:
                template_content = '"author: Your name"\n"title: Your title"\n"lang: en"\n\n"## Output formats"\n\n"# Uncomment and fill to generate files"\n"# output.html: some_file.html"\n"# output.epub: some_file.epub"\n"# output.pdf: some_file.pdf"\n\n"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file\'s name"\n"# output: [pdf, epub, html]"\n\n"# Uncomment and fill to set cover image (for EPUB)"\n"# cover: some_cover.png"\n\n## List of chapters\n'
                for f in create_files:
                    template_content+=f"+ {f}\n"
                with open(create_output, "w", encoding="utf-8") as fh:
                    fh.write(template_content)
                sys.stdout.write(f"Created {create_output}, now you'll have to complete it!\n")
                if not quiet:
                    sys.stderr.write(prefix)
                sys.exit(0)
        else:
            template_content = '"author: Your name"\n"title: Your title"\n"lang: en"\n\n"## Output formats"\n\n"# Uncomment and fill to generate files"\n"# output.html: some_file.html"\n"# output.epub: some_file.epub"\n"# output.pdf: some_file.pdf"\n\n"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file\'s name"\n"# output: [pdf, epub, html]"\n\n"# Uncomment and fill to set cover image (for EPUB)"\n"# cover: some_cover.png"\n\n## List of chapters\n'
            for f in create_files:
                template_content+=f"+ {f}\n"
            sys.stdout.write(template_content)
            if not quiet:
                sys.stderr.write(prefix)
            sys.exit(0)
    if has_stats:
        book=parsed['book']
        if book is None:
            prefix=crowbook_prefix(quiet, force_emoji)
            if not quiet:
                sys.stderr.write(prefix)
                sys.stderr.write("ERROR You must pass the name of a book configuration file.\nFor more information try --help.\n\n")
            else:
                sys.stderr.write("ERROR You must pass the name of a book configuration file.\nFor more information try --help.\n\n")
            sys.exit(0)
