   </script>


  </head>
  <body>


    <div id = "content">
      <div id = "page">
        <header>

          <div id = "menu">

          </div>
	  {header}


        </header>

        {chapters_combined}
      </div>

    </div>
  </body>
</html>
"""
    os.makedirs(os.path.dirname(os.path.abspath(output_path)) if os.path.dirname(output_path) else ".", exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(full_html)

