                with open(chap_path, "w", encoding="utf-8") as f:
                    f.write(xhtml)
            with open(os.path.join(oebps, "content.opf"), "w", encoding="utf-8") as f:
                f.write(f'<?xml version="1.0" encoding="UTF-8"?><package version="3.0" xmlns="http://www.idpf.org/2007/opf"><metadata><dc:title xmlns:dc="http://purl.org/dc/elements/1.1/">{title}</dc:title><dc:creator xmlns:dc="http://purl.org/dc/elements/1.1/">{author}</dc:creator><dc:language xmlns:dc="http://purl.org/dc/elements/1.1/">{book_lang}</dc:language></metadata><manifest><item id="stylesheet" href="stylesheet.css" media-type="text/css"/>')
                for idx in range(len(chapters_html)):
                    f.write(f'<item id="chapter_{idx:03d}" href="chapter_{idx:03d}.xhtml" media-type="application/xhtml+xml"/>')
                f.write('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/><item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/></manifest><spine toc="ncx"><itemref idref="chapter_000" />')
                for idx in range(1,len(chapters_html)):
                    f.write(f'<itemref idref="chapter_{idx:03d}" />')
                f.write('</spine></package>')
            with open(os.path.join(oebps, "toc.ncx"), "w", encoding="utf-8") as f:
