                    f.write(tp)
            os.makedirs(os.path.dirname(os.path.abspath(output_epub)) if os.path.dirname(output_epub) else ".", exist_ok=True)
            with zipfile.ZipFile(output_epub, 'w') as z:
                z.write(os.path.join(tmpdir, "mimetype"), "mimetype", compress_type=zipfile.ZIP_STORED)
