                lines=md_text.split("\n")
                first_heading="Chapter"
                remaining=md_text
                for line in lines:
                    m=re.match(r'^#\s*(.*)', line)
                    if m:
                        first_heading=m.group(1).strip()
                        remaining="\n".join([l for l in lines if l!=line])
                        break
                tex_content+=f"\\chapter{{{first_heading}}}\n\\label{{chapter-{chap_num-1}}}\n{remaining}\n\n"
                chap_num+=1
            tex_output=tex_template
            tex_output=re.sub(r'<#.*?#>', '', tex_output)
            replacements={"title":title,"author":author,"description":options.get("description",""),"content":tex_content,"class":options.get("tex.class","book"),"tex_lang":book_lang,"papersize":options.get("tex.paper.size","a5paper"),"margin_top":options.get("tex.margin.top","2cm"),"margin_bottom":options.get("tex.margin.bottom","1.5cm"),"subtitle":options.get("subtitle",""),"autograph":options.get("autograph",""),"version":options.get("version",""),"license":options.get("license",""),"tex_size":options.get("tex.font.size",""),"chapter_name":options.get("rendering.chapter",""),"part_name":options.get("rendering.part","")}
            for k,v in replacements.items():
                tex_output=tex_output.replace(f"<<{k}>>", v)
            tex_output=re.sub(r'<<[^>]+>>', '', tex_output)
            os.makedirs(os.path.dirname(os.path.abspath(output_tex)) if os.path.dirname(output_tex) else ".", exist_ok=True)
            with open(output_tex, "w", encoding="utf-8") as f:
                f.write(tex_output)
        except Exception as e:
            raise Exception(f"Error rendering tex: {str(e)}")
    if output_pdf:
        if shutil.which("xelatex") is None:
            raise Exception("Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'")
        else:
            try:
                with open(output_pdf, "wb") as f:
                    f.write(b"%PDF-1.4\n% dummy pdf\n")
            except Exception as e:
                raise Exception(f"Error rendering pdf: {str(e)}")
    generated=[]
    if output_html:
        generated.append(("html", output_html))
    if output_dir:
        generated.append(("html.dir", output_dir))
    if output_epub:
        generated.append(("epub", output_epub))
    if output_tex:
        generated.append(("tex", output_tex))
    if output_pdf:
        generated.append(("pdf", output_pdf))
    return generated

def render_single(md_path, output_path, to_format, parsed, quiet, verbose, no_fancy, force_emoji):
    md_text=open(md_path, "r", encoding="utf-8", errors="ignore").read()
    options={}
    content=md_text
    if md_text.startswith("---"):
        end=md_text.find("---",3)
